351	// AppendReviewTrailers appends all Entire-Review-* trailers to a commit
352	// message in trailer-aware format (single blank line separating body from
353	// trailer block).
354	func AppendReviewTrailers(message string, md ReviewMetadata) string {
355		trailers := []struct {
356			key, val string
357		}{
358			{ReviewByTrailerKey, md.By},
359			{ReviewAgentTrailerKey, md.Agent},
360			{ReviewSkillsTrailerKey, strings.Join(md.Skills, ",")},
361			{ReviewSessionTrailerKey, md.Session},
362			{ReviewCheckpointTrailerKey, md.Checkpoint},
363			{ReviewedUpToTrailerKey, md.ReviewedUpTo},
364			{ReviewStatusTrailerKey, md.Status},
365		}
366		out := message
367		for _, tr := range trailers {
368			if tr.val == "" {
369				continue
370			}
371			out = appendTrailerLine(out, fmt.Sprintf("%s: %s", tr.key, tr.val))
372		}
373		return out
374	}
