55	// WritePendingReviewMarker persists the marker. Overwrites any existing marker
56	// — callers detect concurrent reviews via ReadPendingReviewMarker before this.
57	func WritePendingReviewMarker(m PendingReviewMarker) error {
58		path, err := pendingMarkerPath()
59		if err != nil {
60			return err
61		}
62		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
63			return fmt.Errorf("create sessions dir: %w", err)
64		}
65		data, err := json.MarshalIndent(m, "", "  ")
66		if err != nil {
67			return fmt.Errorf("marshal marker: %w", err)
68		}
69		if err := os.WriteFile(path, data, 0o600); err != nil {
70			return fmt.Errorf("write marker: %w", err)
71		}
72		return nil
73	}
