75	// ReadPendingReviewMarker returns the marker if one exists.
76	// ok=false with err=nil indicates "no pending review."
77	func ReadPendingReviewMarker() (PendingReviewMarker, bool, error) {
78		path, err := pendingMarkerPath()
79		if err != nil {
80			return PendingReviewMarker{}, false, err
81		}
82		data, err := os.ReadFile(path) //nolint:gosec // path derived from git dir
83		if errors.Is(err, os.ErrNotExist) {
84			return PendingReviewMarker{}, false, nil
85		}
86		if err != nil {
87			return PendingReviewMarker{}, false, fmt.Errorf("read marker: %w", err)
88		}
89		var m PendingReviewMarker
90		if err := json.Unmarshal(data, &m); err != nil {
91			return PendingReviewMarker{}, false, fmt.Errorf("parse marker: %w", err)
92		}
93		return m, true, nil
94	}
