135	// adoptPendingReviewMarkerInto reads any pending review marker and applies it
136	// to the given session state. Returns (newState, modified, error). If the
137	// state already has Kind set (e.g., a subsequent turn of a review session),
138	// the marker is left in place and modified=false — adoption only happens on
139	// first tag. The marker is cleared on successful first adoption.
140	func adoptPendingReviewMarkerInto(ctx context.Context, s session.State) (session.State, bool, error) {
141		// Already tagged — don't re-apply on subsequent turns.
142		if s.Kind != "" {
143			return s, false, nil
144		}
145		m, ok, err := ReadPendingReviewMarker()
146		if err != nil {
147			return s, false, err
148		}
149		if !ok {
150			return s, false, nil
151		}
152		s.Kind = session.KindReview
153		s.ReviewStatus = session.ReviewStatusInProgress
154		s.ReviewSkills = m.Skills
155		if err := ClearPendingReviewMarker(); err != nil {
156			// Tagging succeeded; leftover marker self-heals on next session start
157			// (since Kind is now set, the next turn will return modified=false
158			// and the marker will be re-cleared on any next review session).
159			logging.Warn(ctx, "failed to clear pending review marker", slog.String("error", err.Error()))
160		}
161		return s, true, nil
162	}
