164	// runReviewConfigPicker presents a huh multi-select for each installed agent
165	// that has curated review skills, and saves the selection to
166	// .entire/settings.json. Returns the picked configuration so callers can
167	// proceed immediately without re-reading from disk.
168	//
169	
170	func runReviewConfigPicker(ctx context.Context, out io.Writer) (map[string][]string, error) {
171		installed := GetAgentsWithHooksInstalled(ctx)
172		if len(installed) == 0 {
173			return nil, errors.New("no agents installed; run 'entire enable' first")
174		}
175		selected := map[string][]string{}
176		for _, agentName := range installed {
177			curated, ok := curatedReviewSkills[string(agentName)]
178			if !ok || len(curated) == 0 {
179				// Agent has no curated list; user must edit JSON manually.
180				continue
181			}
182			var picks []string
183			options := make([]huh.Option[string], 0, len(curated))
184			for _, s := range curated {
185				options = append(options, huh.NewOption(fmt.Sprintf("%s — %s", s.Name, s.Desc), s.Name))
186			}
187			form := NewAccessibleForm(huh.NewGroup(
188				huh.NewMultiSelect[string]().
189					Title(fmt.Sprintf("Pick review skills for %s", agentName)).
190					Options(options...).
191					Value(&picks),
192			))
193			if err := form.Run(); err != nil {
194				return nil, fmt.Errorf("picker for %s: %w", agentName, err)
195			}
196			if len(picks) > 0 {
197				selected[string(agentName)] = picks
198			}
199		}
200		if len(selected) == 0 {
201			return nil, errors.New("no review skills selected")
202		}
203		if err := saveReviewConfig(ctx, selected); err != nil {
204			return nil, err
205		}
206		fmt.Fprintln(out, "Saved review config to .entire/settings.json. Edit directly or run `entire review --edit`.")
207		return selected, nil
208	}
