257	func runReview(ctx context.Context, cmd *cobra.Command, trackOnly bool) error {
258		out := cmd.OutOrStdout()
259	
260		// 1. Pre-flight: must be in a git repo.
261		if _, err := paths.WorktreeRoot(ctx); err != nil {
262			cmd.SilenceUsage = true
263			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
264			return NewSilentError(errors.New("not a git repository"))
265		}
266	
267		// 2. Load config; trigger first-run picker if missing.
268		s, err := settings.Load(ctx)
269		if err != nil || s == nil || len(s.Review) == 0 {
270			picked, pickErr := runReviewConfigPicker(ctx, out)
271			if pickErr != nil {
272				return pickErr
273			}
274			s = &settings.EntireSettings{Review: picked}
275		}
276	
277		// 3. Pick agent.
278		agentName, skills, err := selectReviewAgent(s.Review)
279		if err != nil {
280			return err
281		}
282	
283		// 4. Re-run guard. (Real implementation lands in Chunk 8.)
284		if reviewed, meta := branchReviewedAtHead(ctx); reviewed {
285			if !confirmReRun(out, meta) {
286				fmt.Fprintln(out, "Review cancelled.")
287				return nil
288			}
289		}
290	
291		// 5. Resolve HEAD for the pending marker.
292		headSHA, err := currentHeadSHA(ctx)
293		if err != nil {
294			return fmt.Errorf("resolve HEAD: %w", err)
295		}
296	
297		// 6. Write pending marker (agent hook will adopt it).
298		if err := WritePendingReviewMarker(PendingReviewMarker{
299			AgentName:   agentName,
300			Skills:      skills,
301			StartingSHA: headSHA,
302			StartedAt:   time.Now().UTC(),
303		}); err != nil {
304			return fmt.Errorf("write pending marker: %w", err)
305		}
306	
307		if trackOnly {
308			fmt.Fprintln(out, "Pending review marker written.")
309			fmt.Fprintf(out, "Start %s and run these skills manually: %s\n", agentName, strings.Join(skills, ", "))
310			fmt.Fprintln(out, "When done, run `/entire-review:finish` in the agent.")
311			return nil
312		}
313	
314		// 7. Spawn agent with the composed initial prompt.
315		launcher, ok := agent.LauncherFor(types.AgentName(agentName))
316		if !ok {
317			fmt.Fprintf(out, "%s does not support subprocess launch yet. Falling back to --track-only.\n", agentName)
318			fmt.Fprintf(out, "Start %s manually and run: %s, then /entire-review:finish\n", agentName, strings.Join(skills, ", "))
319			return nil
320		}
321		prompt := composeReviewPrompt(skills)
322		execCmd, err := launcher.LaunchCmd(ctx, prompt)
323		if err != nil {
324			return fmt.Errorf("launch %s: %w", agentName, err)
325		}
326		if err := execCmd.Run(); err != nil {
327			return fmt.Errorf("agent exited: %w", err)
328		}
329		return nil
330	}
