332	// selectReviewAgent picks an agent from the configured review map. v1: single
333	// agent. If multiple are configured, returns the one that sorts first by name
334	// (deterministic default). Returns an error if the map is empty.
335	func selectReviewAgent(review map[string][]string) (string, []string, error) {
336		if len(review) == 0 {
337			return "", nil, errors.New("no review skills configured")
338		}
339		// Deterministic pick: alphabetical by agent name.
340		var names []string
341		for name, skills := range review {
342			if len(skills) > 0 {
343				names = append(names, name)
344			}
345		}
346		if len(names) == 0 {
347			return "", nil, errors.New("no review skills configured")
348		}
349		sort.Strings(names)
350		pick := names[0]
351		return pick, review[pick], nil
352	}
