354	// composeReviewPrompt builds the initial prompt the agent receives.
355	func composeReviewPrompt(skills []string) string {
356		var sb strings.Builder
357		sb.WriteString("Please run these review skills in order:\n")
358		for i, skill := range skills {
359			fmt.Fprintf(&sb, "  %d. %s\n", i+1, skill)
360		}
361		sb.WriteString("\nWhen all skills have completed, run /entire-review:finish to present options to the user.\n")
362		return sb.String()
