365	// currentHeadSHA returns the current HEAD commit hash as a 40-char hex string.
366	func currentHeadSHA(ctx context.Context) (string, error) {
367		repoRoot, err := paths.WorktreeRoot(ctx)
368		if err != nil {
369			return "", fmt.Errorf("locate repo root: %w", err)
370		}
371		execCmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "rev-parse", "HEAD")
372		output, err := execCmd.Output()
373		if err != nil {
374			return "", fmt.Errorf("git rev-parse HEAD: %w", err)
375		}
376		return strings.TrimSpace(string(output)), nil
377	}
