391	// findMostRecentReview walks HEAD's history backwards and returns the first
392	// commit whose message parses as a review (has Entire-Review-* trailers).
393	// Returns ok=false with err=nil when no review commit exists in history.
394	func findMostRecentReview(ctx context.Context) (reviewInfo, bool, error) {
395		repoRoot, err := paths.WorktreeRoot(ctx)
396		if err != nil {
397			return reviewInfo{}, false, fmt.Errorf("resolve repo root: %w", err)
398		}
399		repo, err := git.PlainOpen(repoRoot)
400		if err != nil {
401			return reviewInfo{}, false, fmt.Errorf("open repo: %w", err)
402		}
403		head, err := repo.Head()
404		if err != nil {
405			return reviewInfo{}, false, fmt.Errorf("resolve HEAD: %w", err)
406		}
407		iter, err := repo.Log(&git.LogOptions{From: head.Hash()})
408		if err != nil {
409			return reviewInfo{}, false, fmt.Errorf("walk history: %w", err)
410		}
411		defer iter.Close()
412	
413		var found reviewInfo
414		var ok bool
415		walked := 0
416		iterErr := iter.ForEach(func(c *object.Commit) error {
417			if md, isReview := trailers.ParseReviewMetadata(c.Message); isReview {
418				found = reviewInfo{
419					CommitHash:   c.Hash,
420					By:           md.By,
421					Agent:        md.Agent,
422					Session:      md.Session,
423					Checkpoint:   md.Checkpoint,
424					ReviewedUpTo: md.ReviewedUpTo,
425					Status:       md.Status,
426					CommitsSince: walked,
427				}
428				ok = true
429				return storer.ErrStop
430			}
431			walked++
432			return nil
433		})
434		if iterErr != nil && !errors.Is(iterErr, storer.ErrStop) {
435			return reviewInfo{}, false, fmt.Errorf("walk commits: %w", iterErr)
436		}
437		return found, ok, nil
