615	// createReviewCommit writes an empty "Review" commit on the current branch
616	// with review trailers. Reviewed-Up-To is set to HEAD (before the commit)
617	// so it doesn't point at the new commit itself.
618	func createReviewCommit(ctx context.Context, md trailers.ReviewMetadata) (plumbing.Hash, error) {
619		repoRoot, err := paths.WorktreeRoot(ctx)
620		if err != nil {
621			return plumbing.ZeroHash, fmt.Errorf("locate repo root: %w", err)
622		}
623		repo, err := git.PlainOpen(repoRoot)
624		if err != nil {
625			return plumbing.ZeroHash, fmt.Errorf("open repo: %w", err)
626		}
627		head, err := repo.Head()
628		if err != nil {
629			return plumbing.ZeroHash, fmt.Errorf("resolve HEAD: %w", err)
630		}
631		if !head.Name().IsBranch() {
632			return plumbing.ZeroHash, errors.New("cannot create review commit: not on a branch (detached HEAD)")
633		}
634		parent, err := repo.CommitObject(head.Hash())
635		if err != nil {
636			return plumbing.ZeroHash, fmt.Errorf("load parent commit: %w", err)
637		}
638		md.ReviewedUpTo = head.Hash().String()
639		message := trailers.AppendReviewTrailers("Review\n", md)
640	
641		author, err := GetGitAuthor(ctx)
642		if err != nil {
643			return plumbing.ZeroHash, fmt.Errorf("resolve git author: %w", err)
644		}
645		now := time.Now()
646		commit := &object.Commit{
647			Author:       object.Signature{Name: author.Name, Email: author.Email, When: now},
648			Committer:    object.Signature{Name: author.Name, Email: author.Email, When: now},
649			Message:      message,
650			TreeHash:     parent.TreeHash,
651			ParentHashes: []plumbing.Hash{parent.Hash},
652		}
653		obj := repo.Storer.NewEncodedObject()
654		if err := commit.Encode(obj); err != nil {
655			return plumbing.ZeroHash, fmt.Errorf("encode commit: %w", err)
656		}
657		hash, err := repo.Storer.SetEncodedObject(obj)
658		if err != nil {
659			return plumbing.ZeroHash, fmt.Errorf("store commit: %w", err)
660		}
661		// Advance the current branch to point at the new commit.
662		ref := plumbing.NewHashReference(head.Name(), hash)
663		if err := repo.Storer.SetReference(ref); err != nil {
664			return plumbing.ZeroHash, fmt.Errorf("update branch ref: %w", err)
665		}
666		return hash, nil
667	}
