func TestAppendReviewTrailers(t *testing.T) {
	t.Parallel()
	msg := "Review\n"
	out := AppendReviewTrailers(msg, ReviewMetadata{
		By:           "peyton@entire.io",
		Agent:        "claude-code",
		Skills:       []string{"/pr-review-toolkit:review-pr", "/test-auditor"},
		Session:      "2026-04-20-uuid",
		Checkpoint:   "a3b2c4d5e6f7",
		ReviewedUpTo: "0123456789abcdef0123456789abcdef01234567",
		Status:       "closed",
	})
	wantSubstrings := []string{
		"Entire-Review-By: peyton@entire.io",
		"Entire-Review-Agent: claude-code",
		"Entire-Review-Skills: /pr-review-toolkit:review-pr,/test-auditor",
		"Entire-Review-Session: 2026-04-20-uuid",
		"Entire-Review-Checkpoint: a3b2c4d5e6f7",
		"Entire-Reviewed-Up-To: 0123456789abcdef0123456789abcdef01234567",
		"Entire-Review-Status: closed",
	}
	for _, s := range wantSubstrings {
		if !strings.Contains(out, s) {
			t.Errorf("output missing %q\n---\n%s", s, out)
		}
	}
}

func TestParseReviewMetadata(t *testing.T) {
	t.Parallel()
	msg := `Review

Entire-Review-By: peyton@entire.io
Entire-Review-Agent: claude-code
Entire-Review-Skills: /pr-review-toolkit:review-pr,/test-auditor
Entire-Review-Session: 2026-04-20-uuid
Entire-Review-Checkpoint: a3b2c4d5e6f7
Entire-Reviewed-Up-To: 0123456789abcdef0123456789abcdef01234567
Entire-Review-Status: closed
`
	md, ok := ParseReviewMetadata(msg)
	if !ok {
		t.Fatal("expected review metadata to parse")
	}
	if md.By != "peyton@entire.io" {
		t.Errorf("By = %q", md.By)
	}
	if len(md.Skills) != 2 || md.Skills[1] != "/test-auditor" {
		t.Errorf("Skills = %v", md.Skills)
	}
	if md.Status != "closed" {
		t.Errorf("Status = %q", md.Status)
	}
}

func TestReviewMetadataRoundTrip(t *testing.T) {
	t.Parallel()

	original := ReviewMetadata{
		By:           "peyton@entire.io",
		Agent:        "claude-code",
		Skills:       []string{"/pr-review-toolkit:review-pr", "/test-auditor"},
		Session:      "2026-04-20-uuid",
		Checkpoint:   "a3b2c4d5e6f7",
		ReviewedUpTo: "0123456789abcdef0123456789abcdef01234567",
		Status:       "closed",
	}

	// Append trailers to a message
	msg := "Review\n"
	msg = AppendReviewTrailers(msg, original)

	// Parse it back
	parsed, ok := ParseReviewMetadata(msg)
	if !ok {
		t.Fatal("ParseReviewMetadata returned ok=false after AppendReviewTrailers")
	}

	// Verify all fields match
	if parsed.By != original.By {
		t.Errorf("By: got %q, want %q", parsed.By, original.By)
	}
	if parsed.Agent != original.Agent {
		t.Errorf("Agent: got %q, want %q", parsed.Agent, original.Agent)
	}
	if len(parsed.Skills) != len(original.Skills) {
		t.Errorf("Skills length: got %d, want %d", len(parsed.Skills), len(original.Skills))
	} else {
		for i := range original.Skills {
			if parsed.Skills[i] != original.Skills[i] {
				t.Errorf("Skills[%d]: got %q, want %q", i, parsed.Skills[i], original.Skills[i])
			}
		}
	}
	if parsed.Session != original.Session {
		t.Errorf("Session: got %q, want %q", parsed.Session, original.Session)
	}
	if parsed.Checkpoint != original.Checkpoint {
		t.Errorf("Checkpoint: got %q, want %q", parsed.Checkpoint, original.Checkpoint)
	}
	if parsed.ReviewedUpTo != original.ReviewedUpTo {
		t.Errorf("ReviewedUpTo: got %q, want %q", parsed.ReviewedUpTo, original.ReviewedUpTo)
	}
	if parsed.Status != original.Status {
		t.Errorf("Status: got %q, want %q", parsed.Status, original.Status)
	}
}

func TestParseReviewMetadata_PartialTrailers(t *testing.T) {
	t.Parallel()

	// Test that ok=true when only one trailer is present (not just By)
	tests := []struct {
		name    string
