			message: "Review\n\nEntire-Review-Skills: /skill1,/skill2\n",
			field:   "Skills",
			value:   "/skill1", // Just check first element
		},
		{
			name:    "only Session trailer",
			message: "Review\n\nEntire-Review-Session: 2026-04-20-uuid\n",
			field:   "Session",
			value:   "2026-04-20-uuid",
