			message: "Review\n\nEntire-Review-Status: closed\n",
			field:   "Status",
			value:   "closed",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			md, ok := ParseReviewMetadata(tt.message)
			if !ok {
				t.Error("ParseReviewMetadata returned ok=false; expected ok=true")
