					t.Errorf("Skills[0]: got %v, want %q", md.Skills, tt.value)
				}
			case "Session":
				if md.Session != tt.value {
					t.Errorf("Session: got %q, want %q", md.Session, tt.value)
				}
			case "Checkpoint":
				if md.Checkpoint != tt.value {
					t.Errorf("Checkpoint: got %q, want %q", md.Checkpoint, tt.value)
				}
			case "ReviewedUpTo":
